      "styleHtml": "@import url(\"https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap\");\n@import url(\"https://fonts.googleapis.com/css2?family=EB+Garamond:ital,wght@0,400..800;1,400..800&amp;family=Inter:wght@100..900&amp;family=Playfair+Display:ital,wght@0,400..900;1,400..900&amp;display=swap\");\n@import url(\"https://fonts.googleapis.com/css2?family=Material+Symbols+Outlined:wght,FILL@100..700,0..1&amp;display=swap\");\n\n        /* Custom Utilities for Tactile Editorial Style */\n        .inner-shadow-impression {\n            box-shadow: inset 0 2px 4px 0 rgba(28, 27, 27, 0.05);\n        }\n        .hairline-border {\n            border-width: 0.5px;\n        }\n        .vellum-blur {\n            backdrop-filter: blur(20px);\n            -webkit-backdrop-filter: blur(20px);\n        }\n        .film-grain {\n            position: relative;\n        }\n        .film-grain::after {\n            content: \"\";\n            position: absolute;\n            top: 0; left: 0; right: 0; bottom: 0;\n            background-image: url(\"data:image/svg+xml,%3Csvg viewBox='0 0 200 200' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='noiseFilter'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.85' numOctaves='3' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23noiseFilter)' opacity='0.05'/%3E%3C/svg%3E\");\n            pointer-events: none;\n            z-index: 10;\n        }\n    \n\n.friday-stitch-page {\n  min-height: 100vh;\n  overflow-x: hidden;\n  background: #fff;\n  color: #111;\n}\n.friday-stitch-page .friday-stitch-html {\n  min-height: 100vh;\n  overflow-x: hidden;\n}\n.friday-stitch-page h1 {\n  font-size: clamp(2.4rem, 5vw, 4.8rem) !important;\n  line-height: 1.05 !important;\n  letter-spacing: 0 !important;\n}\n.friday-stitch-page h2 {\n  font-size: clamp(1.5rem, 3vw, 2.75rem) !important;\n  line-height: 1.15 !important;\n  letter-spacing: 0 !important;\n}\n.friday-stitch-page p {\n  max-width: 76ch;\n}\n.friday-stitch-page img {\n  max-width: 100%;\n  height: auto;\n}\n.friday-stitch-page button,\n.friday-stitch-page a {\n  min-height: 40px;\n}\n@media (min-width: 768px) {\n  .friday-stitch-page section {\n    scroll-margin-top: 88px;\n  }\n}",
      "summary": "Hand-crafted provenance. Every suite is an archival artifact, born from deep letterpress impressions and heritage paper stocks.",
